import os
import json
import logging
from pathlib import Path
from typing import List, Dict, Any

import requests
from fastapi import APIRouter, HTTPException

router = APIRouter()
logger = logging.getLogger(__name__)

# Path to the ML results generated by the pipeline
ML_RESULTS_PATH = Path(__file__).resolve().parent.parent / "data" / "ml_results.json"

def _load_ml_results() -> Dict[str, Any]:
    if not ML_RESULTS_PATH.is_file():
        logger.error(f"ML results file not found at {ML_RESULTS_PATH}")
        raise FileNotFoundError("ML results not generated yet")
    with open(ML_RESULTS_PATH, "r", encoding="utf-8") as f:
        return json.load(f)

def _build_prompt(ml_data: Dict[str, Any]) -> str:
    # Simple prompt that summarises key insights and asks for actionable recommendations.
    kpis = ml_data.get("kpis", {})
    anomalies = ml_data.get("anomalies", [])[:5]  # limit for brevity
    # Build a concise description
    prompt = "You are a sales analytics expert. Based on the following KPI summary and recent anomalies, provide 3-5 concise business recommendations to improve revenue and reduce risk.\n\n"
    prompt += "KPIs:\n"
    for name, info in kpis.items():
        prompt += f"- {name}: {info.get('formatted', info.get('value'))}\n"
    prompt += "\nTop Anomalies (most severe):\n"
    for a in anomalies:
        sale_id = a.get('sale_id')
        severity = a.get('severity', 'N/A')
        impact = a.get('impact', 'N/A')
        prompt += f"- Sale ID {sale_id}: severity {severity}, impact {impact}\n"
    prompt += "\nProvide short bullet‑point recommendations (max 5)."
    return prompt

@router.get("/recommendations", response_model=List[Dict[str, Any]])
def get_recommendations() -> List[Dict[str, Any]]:
    """Generate AI‑driven business recommendations.

    The endpoint loads the cached ML results, builds a prompt, calls the Groq LLM,
    and returns a list of recommendation objects.
    """
    try:
        ml_data = _load_ml_results()
    except Exception as e:
        logger.error(f"Failed to load ML results: {e}")
        raise HTTPException(status_code=500, detail="ML results unavailable")

    groq_api_key = os.getenv("groq_api_key")
    if not groq_api_key:
        logger.warning("groq_api_key not set – returning placeholder recommendations.")
        return [{"recommendation": "Placeholder: set groq_api_key in .env to enable AI suggestions."}]


    prompt = _build_prompt(ml_data)
    try:
        response = requests.post(
            "https://api.groq.com/openai/v1/chat/completions",
            headers={
                "Authorization": f"Bearer {groq_api_key}",
                "Content-Type": "application/json",
            },
            json={
                "model": "llama3-70b-8192",
                "messages": [
                    {"role": "system", "content": "You are a concise business analyst."},
                    {"role": "user", "content": prompt}
                ],
                "temperature": 0.7,
                "max_tokens": 500,
            },
            timeout=30,
        )
        response.raise_for_status()
        data = response.json()
        text = data["choices"][0]["message"]["content"].strip()
        # Removed redundant OpenAI extraction
        # Split into bullet points
        lines = [line.strip("- ") for line in text.splitlines() if line.strip()]
        recommendations = [{"recommendation": line} for line in lines]
        return recommendations
    except Exception as e:
        logger.error(f"Groq request failed: {e}")
        raise HTTPException(status_code=500, detail="Failed to generate recommendations")
